{
  "name": "state_check_and_setup",
  "confidence": "medium",
  "docstring": "Checks a bounded global state table for ready entries and dispatches linked state nodes through process_flags, updating the global state pointer and object flags when setup succeeds.",
  "subsystem": "ke",
  "var_renames": {
    "a1": "out_ptr",
    "v1": "global_state",
    "v2": "entry_idx",
    "v3": "state_table_base",
    "v5": "current_entry_idx",
    "v6": "result",
    "v7": "entry",
    "v8": "entry_state",
    "v9": "entry_node",
    "v13": "processed_node",
    "v16": "state_object",
    "v17": "object_flags"
  },
  "struct_hints": [
    {
      "offset": 12,
      "meaning": "state_table_entry: pointer to associated node/message/queue entry"
    },
    {
      "offset": 26,
      "meaning": "state_table_entry: uint8 state/ready flag; value 1 selects the tail path"
    },
    {
      "offset": 36,
      "meaning": "state_table_entry: table/base pointer or index field used to compute the returned address"
    },
    {
      "offset": 68,
      "meaning": "state_node: pointer to object/buffer whose status word at offset 8 is updated on success"
    },
    {
      "offset": 176,
      "meaning": "global_state: uint32 passed as process_flags argument"
    },
    {
      "offset": 186,
      "meaning": "global_state: uint16 passed as process_flags argument"
    },
    {
      "offset": 190,
      "meaning": "global_state: uint8 current entry index/selector"
    },
    {
      "offset": 197,
      "meaning": "global_state: uint8 active entry count/limit; values above 3 are invalid"
    },
    {
      "offset": 204,
      "meaning": "global_state: uint32 result object pointer set after successful setup"
    },
    {
      "offset": 8,
      "meaning": "state_object: uint16 status/flag word; bit 0x200 is set after setup"
    }
  ]
}
